import { useMemo, useState } from "react";
import { FieldFrame, PageHeader, Select, StatusPill } from "@autograph/components";
import { DataTableComposition, RecordDetailPanel } from "@autograph/compositions";

const exceptions = [
  {id:"ex-101",product:"Organic Whole Milk 1L",sku:"DRY-1048",location:"Downtown",severity:"Critical",onHand:3,reorderPoint:18,daysCover:0.6,supplier:"North Valley Dairy",leadTime:"2 days",packSize:12,suggested:36},
  {id:"ex-102",product:"Sparkling Water Lime 8pk",sku:"BEV-2281",location:"Downtown",severity:"Warning",onHand:9,reorderPoint:16,daysCover:2.1,supplier:"Clear Springs Co.",leadTime:"4 days",packSize:8,suggested:24},
  {id:"ex-103",product:"Free-range Eggs 12ct",sku:"DRY-1312",location:"Riverside",severity:"Critical",onHand:2,reorderPoint:14,daysCover:0.4,supplier:"Meadow Farm Foods",leadTime:"1 day",packSize:10,suggested:30},
  {id:"ex-104",product:"Sourdough Sandwich Loaf",sku:"BAK-0782",location:"Riverside",severity:"Warning",onHand:6,reorderPoint:12,daysCover:1.8,supplier:"City Bakehouse",leadTime:"1 day",packSize:6,suggested:18},
  {id:"ex-105",product:"Avocado Hass Each",sku:"PRD-0426",location:"Northside",severity:"Critical",onHand:5,reorderPoint:24,daysCover:0.8,supplier:"Pacific Produce",leadTime:"3 days",packSize:24,suggested:48},
  {id:"ex-106",product:"Greek Yogurt Plain 500g",sku:"DRY-1159",location:"Northside",severity:"Warning",onHand:7,reorderPoint:15,daysCover:2.3,supplier:"North Valley Dairy",leadTime:"2 days",packSize:6,suggested:18},
];

export default function StockExceptions() {
  const [location,setLocation] = useState("all");
  const [severity,setSeverity] = useState("all");
  const [selectedId,setSelectedId] = useState("ex-101");
  const [detailTab,setDetailTab] = useState("stock");
  const [replenished,setReplenished] = useState<string[]>([]);
  const visible = useMemo(() => exceptions.filter(item =>
    (location === "all" || item.location === location) &&
    (severity === "all" || item.severity === severity)), [location,severity]);
  const selected = visible.find(item => item.id === selectedId) ?? visible[0];
  const done = selected ? replenished.includes(selected.id) : false;
  return <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-6)] text-[var(--color-text-primary)]">
    <div className="mx-auto grid max-w-[1440px] gap-[var(--space-5)]">
      <PageHeader title="Stock exceptions" subtitle={`${visible.length} ${visible.length === 1 ? "product needs" : "products need"} review · Select a product to review and replenish`} />
      <section aria-label="Exception filters" className="grid grid-cols-2 gap-[var(--space-4)] max-w-[680px]">
        <FieldFrame label="Location" htmlFor="location-filter"><Select id="location-filter" value={location} options={[{value:"all",label:"All locations"},{value:"Downtown",label:"Downtown"},{value:"Riverside",label:"Riverside"},{value:"Northside",label:"Northside"}]} onValueChange={setLocation} /></FieldFrame>
        <FieldFrame label="Severity" htmlFor="severity-filter"><Select id="severity-filter" value={severity} options={[{value:"all",label:"All severities"},{value:"Critical",label:"Critical"},{value:"Warning",label:"Warning"}]} onValueChange={setSeverity} /></FieldFrame>
      </section>
      <div className="grid items-start gap-[var(--space-5)] lg:grid-cols-2">
        <section aria-label="Low-stock products">
          <DataTableComposition spec={{type:"data_table",config:{ariaLabel:"Low-stock products",columns:[{id:"product",label:"Product"},{id:"severity",label:"Severity"},{id:"cover",label:"Cover",align:"right"}],rows:visible.map(item=>({id:item.id,product:item.product,severity:item.severity,cover:`${item.daysCover} days`})),density:"regular",emptyLabel:"No stock exceptions match these filters."}}} getRowId={row=>String(row.id)} selectedRowId={selected?.id} onRowSelect={id=>{setSelectedId(id);setDetailTab("stock");}} selectionLabel="Review" />
        </section>
        <aside aria-label="Selected stock exception">
          {selected ? <RecordDetailPanel
            key={selected.id}
            className="max-h-[calc(100dvh-14rem)]"
            title={selected.product}
            subtitle={<div className="grid gap-[var(--space-2)]"><span>{selected.sku} · {selected.location}</span><div className="flex flex-wrap items-center gap-[var(--space-3)]"><StatusPill label={done?"Mock order created":selected.severity} tone={done?"success":selected.severity==="Critical"?"danger":"warning"} /><span>Preview only · No supplier contacted</span></div></div>}
            tabs={[{id:"stock",label:"Stock position"},{id:"supplier",label:"Supplier details"}]}
            activeTabId={detailTab}
            onTabChange={setDetailTab}
            sections={detailTab==="stock" ? [
              {id:"stock",title:"Replenishment summary",collapsible:false,items:[{type:"field",id:"cover",label:"Estimated cover",value:`${selected.daysCover} days`},{type:"field",id:"on-hand",label:"On hand",value:`${selected.onHand} units`},{type:"field",id:"reorder",label:"Reorder point",value:`${selected.reorderPoint} units`},{type:"field",id:"suggested",label:"Suggested order",value:`${selected.suggested} units`}]},
            ] : [
              {id:"supplier",title:"Ordering details",collapsible:false,items:[{type:"field",id:"supplier-name",label:"Supplier",value:selected.supplier},{type:"field",id:"lead-time",label:"Lead time",value:selected.leadTime},{type:"field",id:"pack-size",label:"Order pack",value:`${selected.packSize} units`}]},
            ]}
            actions={[{id:"replenish",label:done?"Simulated — no order sent":`Simulate ${selected.suggested}-unit order`,intent:"primary",disabled:done}]}
            onAction={()=>setReplenished(current=>[...current,selected.id])}
          /> : <RecordDetailPanel title="No products to review" subtitle="Try a different location or severity." sections={[]} />}
        </aside>
      </div>
    </div>
  </main>;
}
